report={'country':'Nigeria','research_date_utc':'2026-11-15','requested_verified_institutions':10,'live_specific_title_verified_institutions':len(V),'shortfall':10-len(V),'completion':'Partial: six genuine catalog-query successes; ten major priorities identified but four of ten priorities live-verified. No claim of ten verified or national top ten.','methodology':'Official collection-size or major-institution/network proxy selection. Anonymous low-volume direct HTTP queries; boundedHTML snapshots. Specific-title queries must return actual bibliographic books. Search-engine snippets/homepage reachability/branch lists are not successes. Failures reflect this environment and moment, not national outage.','verified':V,'ten_major_priorities':priority,'exclusions_and_other_investigations':exclusions,'sources':S,'market':{'best_reuse_family':'Koha','share_claim':'One2025 federal-university survey reports21/40respondents (52.5%). No current whole-country LMS census established.','largest_verified_shared_deployment':'NOUN:42branch/unitchoices,1catalog; only a headquarters record holding verified.','largest_public_network_opportunity':'National Library13.9million reportedvolumes and33states+FCTpresence,2024; restricted automation requires agreement.','second_platform':'NewGenLib at UNILAG and Benin needs new adapter; both searchable but tested holdings empty.','other_live_platform':'Covenant Primo/COLRIS identifiable but robots blockssearch/API.','public_reach_limit':'University and special libraries dominate verified results. Anonymous discovery does not confer borrowing rights. Public-library coverage and external membership must be separately evaluated.'},'app_adapter_tested':False,'permission_cleared':False}
